            ("+", Builtin::Add),
            ("-", Builtin::Sub),
            ("*", Builtin::Mul),
            ("/", Builtin::Div),
            ("dup", Builtin::Dup),
            ("drop", Builtin::Drop),
            ("swap", Builtin::Swap),
            ("over", Builtin::Over),
        ] {
            names.insert(name.to_string(), defs.len());
            defs.push(Definition::Builtin(builtin));
        }
        Forth {
            stack: Vec::new(),
            defs,
            names,
        }
    }

