/// Execute a definition. User definitions are executed iteratively with an
/// explicit frame stack of token iterators, so nested definitions neither
/// recurse nor are expanded eagerly.
fn exec_def(&mut self, idx: usize) -> Result {
    let mut frames: Vec<std::vec::IntoIter<Token>> = Vec::new();
    match &self.defs[idx] {
        Definition::Builtin(b) => return self.exec_builtin(*b),
        Definition::User(tokens) => frames.push(tokens.iter().copied()),
    }
    while let Some(frame) = frames.last_mut() {
        match frame.next() {
            None => {
                frames.pop();
            }
            Some(Token::Num(n)) => self.stack.push(n),
            Some(Token::Word(i)) => match &self.defs[i] {
                Definition::Builtin(b) => self.exec_builtin(*b)?,
                Definition::User(tokens) => frames.push(tokens.iter().copied()),
            },
        }
    }
    Ok(())
}

